SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, c.is_active, COUNT(o.amount) AS amount_count, ROUND(STDDEV(o.amount), 2) AS stddev_amount FROM orders o LEFT JOIN customers c ON o.customer_id = c.id WHERE o.customer_id IN (27, 29, 34) GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END, c.is_active HAVING COUNT(o.amount) > 5 ORDER BY signup_cohort DESC
